// trace joins the otherwise-disconnected planning layers via each quest's optional
// `links` block. Pick exactly one selector:
//   --row <id>   quests whose links.roadmapRow === id
//   --cl <CL-#>  quests whose links.closesCL includes the record
//   --spec <ref> quests whose links.specRef starts with ref
//   --quest <id> reverse view: this quest's links + its child quests (parentQuest)
// It asserts nothing the sealed quest files do not already contain.
function traceRow(quest, portfolioById) {
  const row = portfolioById.get(quest.id);
  const outcome = row ? row.outcome : 'unknown';
  const klass = row ? row.class : '?';
  return `| ${quest.id} | ${klass} | ${outcome} |`;
}

function cmdTrace(root, args) {
  const selectors = ['row', 'cl', 'spec', 'quest'].filter((k) => args[k] !== undefined);
  if (selectors.length !== 1) {
    throw new Error('trace: pass exactly one of --row <id> | --cl <CL-#> | ' +
      '--spec <ref> | --quest <id>');
  }
  const quests = loadAllQuests(root);
  const portfolioById = new Map(buildPortfolio(root).rows.map((r) => [r.id, r]));
  const out = [];
  if (args.quest !== undefined) {
    const id = String(args.quest);
    const self = quests.find((q) => q.id === id);
    if (!self) throw new Error(`trace: no quest "${id}"`);
    const links = self.links || {};
    out.push(`# trace ${id}`, '', '## Links');
    out.push(`- roadmap row: ${links.roadmapRow || '—'}`);
    out.push(`- spec: ${links.specRef || '—'}`);
    out.push(`- closes: ${(links.closesCL || []).join(', ') || '—'}`);
    out.push(`- parent quest: ${links.parentQuest || '—'}`);
    const children = quests.filter((q) => (q.links || {}).parentQuest === id);
    out.push('', `## Child quests — ${children.length}`);
    if (children.length === 0) {
      out.push('_(none)_');
    } else {
      out.push('| id | class | outcome |', '| --- | --- | --- |');
      for (const c of children) out.push(traceRow(c, portfolioById));
    }
    process.stdout.write(`${out.join('\n')}\n`);
    return;
  }
  let match;
  let title;
  if (args.row !== undefined) {
    const v = String(args.row);
    title = `quests for roadmap row ${v}`;
    match = (q) => (q.links || {}).roadmapRow === v;
  } else if (args.cl !== undefined) {
    const v = String(args.cl);
    title = `quests closing ${v}`;
    match = (q) => Array.isArray((q.links || {}).closesCL) && q.links.closesCL.includes(v);
  } else {
    const v = String(args.spec);
    title = `quests for spec ${v}`;
    match = (q) => typeof (q.links || {}).specRef === 'string' && q.links.specRef.startsWith(v);
  }
  const hits = quests.filter(match);
  out.push(`# trace — ${title}`, '', `${hits.length} match(es)`, '');
  if (hits.length > 0) {
    out.push('| id | class | outcome |', '| --- | --- | --- |');
    for (const q of hits) out.push(traceRow(q, portfolioById));
  }
  process.stdout.write(`${out.join('\n')}\n`);
}

function cmdOverview(root, args) {
  if (args.write) {
    const file = writeOverview(root);
    process.stdout.write(`wrote ${path.relative(root, file)}\n`);
    return;
  }
  process.stdout.write(runOverviewCommand(root));
}

function cmdHandoff(root, args) {
  process.stdout.write(runHandoffCommand(root, args));
}

// Tier-2 live-evidence verification of architecture invariants (standing dual of
// doneWhen). `--evaluate` runs each invariant's predicate and records the verdict;
// otherwise status is derived from the event log. Always active (unconditional).
function changedFilesFromArgs(root, args) {
  if (typeof args.changed === 'string') {
    return args.changed.split(',').map((file) => file.trim()).filter(Boolean);
  }
  if (typeof args.since === 'string') {
    const out = spawnSync('git', ['diff', '--name-only', args.since], {cwd: root, encoding: 'utf8'});
    return (out.stdout || '').split('\n').map((file) => file.trim()).filter(Boolean);
  }
  return null;
}

function cmdInvariants(root, args) {
  // --export: write a durable, cross-session status board (a projection, not a store).
  if (args.export) {
    const board = renderInvariantBoard(root, {});
    const out = typeof args.out === 'string' ?
      args.out : path.join(root, 'solve', 'invariant-status.generated.md');
    fs.mkdirSync(path.dirname(out), {recursive: true});
    fs.writeFileSync(out, board);
    process.stdout.write(`wrote ${out}\n`);
    return;
  }
  // --score: local EvoClaw-style coverage/coherence over the repro-backed surface.
  if (args.score) {
    const result = scoreInvariants(root, {evaluate: Boolean(args.evaluate)});
    if (args.json) {
      process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
      return;
    }
    const pct = (value) => (value === null ? 'n/a' : `${Math.round(value * 100)}%`);
    process.stdout.write(
      'standing-invariant score (local, EvoClaw-style — not the external benchmark):\n' +
      `  coverage:  ${result.guardedReproBackedCLs}/${result.reproBackedCLs} repro-backed CLs guarded (${pct(result.coverage)})\n` +
      `  coherence: ${result.held}/${result.liveInvariants} live invariants HELD (${pct(result.coherence)}) ` +
      `[${result.breached} breached, ${result.unguarded} unguarded]\n` +
      `  worklist (unguarded repro-backed CLs): ${result.unguardedReproBackedCLs.join(LOCAL_STR_OWNED_010) || '(none)'}\n`);
    return;
  }
  // on-touched-owner trigger: re-verify invariants whose paths intersect changed files.
  const changedFiles = changedFilesFromArgs(root, args);
  if (changedFiles) {
    const fired = triggerOnTouchedOwner(root, {changedFiles});
    if (args.json) {
      process.stdout.write(`${JSON.stringify(fired, null, 2)}\n`);
      return;
    }
    const lines = fired.transitions.map((t) => `${t.from} -> ${t.to}  ${t.id}`);
    process.stdout.write(
      `on-touched-owner re-verification (${fired.transitions.length} invariant(s)):\n` +
      `${lines.join(LINE_SEPARATOR) || '(none matched the changed files)'}\n`);
    return;
  }
  const out = runInvariantsCommand(root, args);
  if (args.json) {
    process.stdout.write(`${JSON.stringify(out, null, 2)}\n`);
    return;
  }
  if (out.invariants.length === 0) {
    process.stdout.write('no invariants carry a liveEvidence (Tier-2) block.\n');
    return;
  }
  const lines = out.invariants.map((row) => {
    const tags = `[${row.cost || '?'}, ${row.trigger || '?'}]`;
    const ref = row.evidenceRef ? `  <- ${row.evidenceRef}` : '';
    const tally = row.evaluations ?
      `  (${row.evaluations} eval${row.evaluations === 1 ? '' : 's'}, last ${row.verdict})` : '';
    return `${row.status.padEnd(9)} ${row.id}  ${tags}${ref}${tally}`;
  });
  const header = out.evaluated ?
    'standing invariants (evaluated now):' :
    'standing invariants (derived from event log):';
  process.stdout.write(`${header}\n${lines.join('\n')}\n`);
}

const COMMANDS = {
  'start': cmdStart,
  'continue': cmdContinue,
  'land': cmdLand,
  'decompose-rejection': cmdDecomposeRejection,
  'new': cmdNew,
  'run': cmdRun,
  'status': cmdStatus,
  'report': cmdReport,
  'portfolio': cmdPortfolio,
  'meta-ratio': cmdMetaRatio,
  'meta-friction': cmdMetaFriction,
  'cost': cmdCost,
  'frontier': cmdFrontier,
  'overview': cmdOverview,
  'trace': cmdTrace,
  'handoff': cmdHandoff,
  'checkpoint': cmdCheckpoint,
  'invariants': cmdInvariants,
  'probe': cmdProbe,
  'finding': cmdFinding,
  'promote-finding': cmdPromoteFinding,
  'override': cmdOverride,
  'reflect': cmdReflect,
  'step': cmdStep,
  'step-pending': cmdStepPending,
  'next': cmdNext,
  'doctor': cmdDoctor,
  'lint': cmdLint,
  'theory': cmdTheory,
  'health': cmdHealth,
  'ingest-evidence': cmdIngestEvidence,
  'attempt': cmdAttempt,
  'audit': cmdAudit,
  'upgrade': cmdUpgrade,
  'reopen': cmdReopen,
  'park': cmdPark,
  'amend': cmdAmend,
  'inherit-candidate': cmdInheritCandidate,
  'correct-attempt-base': cmdCorrectAttemptBase,
};

function main() {
  const [, , command, ...rest] = process.argv;
  const handler = COMMANDS[command];
  if (!handler) {
    process.stderr.write(
      `usage: solve <${Object.keys(COMMANDS).join(COMMAND_SEPARATOR)}> ` +
      USAGE_ARGUMENTS);
    process.exit(command ? 1 : 0);
    return;
  }
  let args;
  if (command === 'attempt') {
    const dashDashIndex = process.argv.indexOf('--');
    if (dashDashIndex !== -1) {
      const commandArgs = process.argv.slice(3, dashDashIndex);
      const harnessCmd = process.argv.slice(dashDashIndex + 1);
      args = parseArgs(commandArgs);
      args._ = harnessCmd;
    } else {
      args = parseArgs(rest);
    }
  } else {
    args = parseArgs(rest);
  }
  const root = args.root || process.cwd();
  try {
    handler(root, args);
  } catch (error) {
    process.stderr.write(`error: ${error.message}\n`);
    process.exit(1);
  }
}

main();
